CREATE TABLE IF NOT EXISTS games (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, genre TEXT NOT NULL, year INTEGER NOT NULL, rating REAL NOT NULL, completed INTEGER NOT NULL DEFAULT 0, owner_id INTEGER REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, phone TEXT UNIQUE, phone_verified_at INTEGER, telegram_id TEXT UNIQUE, telegram_chat_id TEXT);
CREATE TABLE IF NOT EXISTS auth_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, token_hash TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_auth_sessions_token_hash ON auth_sessions(token_hash);
CREATE INDEX IF NOT EXISTS idx_auth_sessions_expires_at ON auth_sessions(expires_at);
CREATE TABLE IF NOT EXISTS idempotency_records (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, response_json TEXT, status_code INTEGER, created_at INTEGER NOT NULL, UNIQUE(user_id, idempotency_key));
CREATE INDEX IF NOT EXISTS idx_idempotency_created_at ON idempotency_records(created_at);
CREATE TABLE IF NOT EXISTS phone_verifications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, phone TEXT NOT NULL, verification_token TEXT NOT NULL UNIQUE, telegram_user_id TEXT, telegram_chat_id TEXT, confirmation_code_hash TEXT, code_expires_at INTEGER, code_attempts INTEGER NOT NULL DEFAULT 0, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_phone_verifications_token ON phone_verifications(verification_token);
CREATE TABLE IF NOT EXISTS telegram_updates (update_id INTEGER PRIMARY KEY, created_at INTEGER NOT NULL, processed_at INTEGER);
CREATE TABLE IF NOT EXISTS telegram_auth_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, auth_token TEXT NOT NULL UNIQUE, telegram_user_id TEXT, telegram_chat_id TEXT, phone TEXT, confirmation_code_hash TEXT, code_expires_at INTEGER, code_attempts INTEGER NOT NULL DEFAULT 0, completed_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_telegram_auth_requests_token ON telegram_auth_requests(auth_token);
CREATE TABLE IF NOT EXISTS catalog_games (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, external_id TEXT NOT NULL, slug TEXT, title TEXT NOT NULL, normalized_title TEXT NOT NULL, released_at TEXT, release_year INTEGER, genres_json TEXT NOT NULL DEFAULT '[]', cover_url TEXT, source_updated_at TEXT, is_active INTEGER NOT NULL DEFAULT 1, synced_at INTEGER NOT NULL, created_at INTEGER NOT NULL, UNIQUE(source, external_id));
CREATE INDEX IF NOT EXISTS idx_catalog_games_normalized_title ON catalog_games(normalized_title);
CREATE INDEX IF NOT EXISTS idx_catalog_games_release_year ON catalog_games(release_year);
CREATE TABLE IF NOT EXISTS user_games (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, catalog_game_id INTEGER NOT NULL REFERENCES catalog_games(id) ON DELETE RESTRICT, completed INTEGER NOT NULL DEFAULT 0, personal_rating REAL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(user_id, catalog_game_id));
CREATE INDEX IF NOT EXISTS idx_user_games_catalog_game_id ON user_games(catalog_game_id);
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, catalog_game_id INTEGER NOT NULL REFERENCES catalog_games(id) ON DELETE RESTRICT, text TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('pending','published','hidden','rejected')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(user_id, catalog_game_id));
CREATE INDEX IF NOT EXISTS idx_reviews_catalog_status ON reviews(catalog_game_id, status);
CREATE TABLE IF NOT EXISTS sync_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('running','completed','failed','skipped')), trigger_type TEXT NOT NULL, processed_count INTEGER NOT NULL DEFAULT 0, added_count INTEGER NOT NULL DEFAULT 0, error_message TEXT, started_at INTEGER NOT NULL, finished_at INTEGER);
CREATE TABLE IF NOT EXISTS community_posts (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, personal_game_id INTEGER NOT NULL REFERENCES games(id) ON DELETE CASCADE, catalog_game_id INTEGER NOT NULL REFERENCES catalog_games(id) ON DELETE RESTRICT, review_text TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('published','hidden','rejected')), published_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(user_id, personal_game_id));
CREATE INDEX IF NOT EXISTS idx_community_posts_catalog_status ON community_posts(catalog_game_id,status,published_at DESC);
